package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaTlDraft2 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_allahumma_bika_asbahna" to DuaText("Allahumma Bika Asbahna", "O Allah, sa pamamagitan Mo kami pumapasok sa umaga at sa Iyo kami ay pumapasok sa gabi; sa Iyo kami nabubuhay at sa Iyo kami namamatay, at sa Iyo ang muling pagkabuhay.", "Sa umaga.", "Ang Propeta ﷺ ay nagturo sa mga Kasamahan na magsabi ngayong umaga at gabi."),
        "dua_allahumma_bika_amsayna" to DuaText("Allahumma Bika Amsayna", "O Allah, sa pamamagitan Mo kami pumapasok sa gabi at sa Iyo kami ay pumapasok sa umaga; sa Iyo kami nabubuhay at sa Iyo kami namamatay, at sa Iyo ang pagbabalik.", "Sa gabi.", "Ang Propeta ﷺ ay nagturo sa mga Kasamahan na magsabi ngayong umaga at gabi."),
        "dua_afiyah_morning" to DuaText("Pagtatanong kay Afiyah", "O Allah, humihingi ako sa Iyo ng kapatawaran at kapakanan sa mundong ito at sa Kabilang Buhay.", "Ang Propeta ﷺ ay hindi kailanman umalis sa dalawang ito, umaga o gabi.", "Walang sinuman ang nabigyan ng mas mabuti kaysa sa kapakanan."),
        "dua_afini_fi_badani" to DuaText("Kalusugan ng Katawan, Pandinig at Paningin", "O Allah, ipagkaloob mo ang kagalingan sa aking katawan. O Allah, ipagkaloob mo ang kagalingan sa aking pandinig. O Allah, ipagkaloob mo ang kagalingan sa aking paningin. Walang diyos maliban sa Iyo.", "Tatlong beses tuwing umaga at gabi.", "Isang dua para sa kalusugan at proteksyon ng mga pandama."),
        "dua_ya_hayyu_aslih" to DuaText("Iwasto ang Lahat ng Aking Mga Gawain", "O Buhay na Walang Hanggan, O Tagapagtaguyod, sa pamamagitan ng Iyong awa ay humingi ako ng tulong: ituwid ang lahat ng aking mga gawain at huwag mo akong ipaubaya sa aking sarili kahit sa isang kisap-mata.", "Pinayuhan ng Propeta ﷺ si Fatimah (RA) na sabihin ito sa umaga at gabi.", "Paghingi ng tulong kay Allah sa bawat bagay."),
        "dua_subhanallah_adada_khalqihi" to DuaText("Tasbeeh ng Juwayriyah (RA)", "Luwalhati sa Allah at ang lahat ng papuri ay sa Kanya - kasing dami ng Kanyang nilikha, hangga't nakalulugod sa Kanya, katumbas ng bigat ng Kanyang Trono at ng tinta ng Kanyang mga salita.", "Tatlong beses sa umaga - mas matimbang kaysa sa mga oras ng dhikr.", "Ang pagbigkas ng apat na pariralang ito ng tatlong beses ay mas matimbang sa dhikr mula madaling araw hanggang sa kalagitnaan ng umaga."),
        "dua_salawat" to DuaText("Durood-e-Ibrahimi", "O Allah, magpadala ka ng mga panalangin kay Muhammad ﷺ at sa pamilya ni Muhammad tulad ng pagpapadala Mo ng mga panalangin kay Ibrahim (AS) at sa pamilya ni Ibrahim; Ikaw ay Kapuri-puri, Maluwalhati. O Allah, pagpalain Mo si Muhammad ﷺ at ang pamilya ni Muhammad gaya ng pagpapala Mo kay Ibrahim (AS) at ang pamilya ni Ibrahim; Ikaw ay Kapuri-puri, Maluwalhati.", "Salawat sa Propeta ﷺ sa panalangin at sa lahat ng oras.", "Sinuman ang nagpadala ng salawat ng isang beses, ang Allah ay nagpapadala ng sampung awa sa kanya (Muslim 408)."),
        "dua_wudu_after" to DuaText("Pagkatapos ng Wudu", "Ako ay sumasaksi na walang sinumang karapat-dapat sambahin maliban kay Allah, nag-iisa, walang katambal, at si Muhammad ﷺ ay Kanyang alipin at Sugo. O Allah, gawin mo akong kabilang sa mga nagsisisi at sa mga nagpapadalisay sa kanilang sarili.", "Matapos makumpleto ang wudu.", "Ang walong pintuan ng Paraiso ay binuksan para sa kanya upang makapasok sa alinmang kanyang naisin."),
        "dua_wudu_before" to DuaText("Bago ang Wudu", "Sa ngalan ni Allah.", "Sa pagsisimula ng wudu.", "Walang (kumpletong) wudu para sa sinumang hindi nagbanggit ng pangalan ng Allah sa ibabaw nito."),
        "dua_istiftah" to DuaText("Pambungad na Pagsusumamo (Sana)", "Luwalhati sa Iyo, O Allah, at papuri sa Iyo. Mapalad ang Iyong pangalan, dakila ang Iyong kamahalan, at walang diyos maliban sa Iyo.", "Sa pagsisimula ng pagdarasal, pagkatapos ng pambungad na takbir.", "Ang Sunnah pambungad na dua ng panalangin."),
        "dua_ruku" to DuaText("Sa Ruku", "Luwalhati sa aking Panginoon, ang Dakila.", "Hindi bababa sa tatlong beses sa ruku.", "Ang Sunnah tasbih ng ruku."),
        "dua_sujood" to DuaText("Sa Sujood", "Luwalhati sa aking Panginoon, ang Kataas-taasan.", "Hindi bababa sa tatlong beses sa sujood.", "Ang alipin ay pinakamalapit sa kanyang Panginoon habang nakadapa (Muslim 482)."),
        "dua_rising_ruku" to DuaText("Bumangon mula sa Ruku", "Naririnig ng Allah ang pumupuri sa Kanya. Panginoon namin, sa Iyo ang lahat ng papuri.", "Habang tumatayo mula sa ruku at nakatayo ng tuwid.", "Sinuman ang 'Rabbana wa lakal-hamd' na kasabay ng sa mga anghel, ang kanyang mga nakaraang kasalanan ay pinatawad."),
        "dua_between_sajdas" to DuaText("Sa pagitan ng Dalawang Sajdas", "Panginoon ko, patawarin mo ako. Panginoon ko, patawarin mo ako.", "Habang nakaupo sa pagitan ng dalawang pagpapatirapa.", "Ang Sunnah dua ng pag-upo sa pagitan ng mga pagpapatirapa."),
        "dua_before_salam_four" to DuaText("Kanlungan mula sa Apat na Bagay (Bago ang Salam)", "O Allah, ako ay nagpapakupkop sa Iyo mula sa kaparusahan ng Impiyerno, mula sa parusa sa libingan, mula sa mga pagsubok sa buhay at kamatayan, at mula sa kasamaan ng pagsubok ng Huwad na Mesiyas (Dajjal).", "Pagkatapos ng huling tashahhud at salawat, bago ang salam.", "Ang Propeta ﷺ ay nag-utos na humingi ng kanlungan mula sa apat na bagay na ito."),
        "dua_qunoot_witr" to DuaText("Qunoot sa Witr", "O Allah, patnubayan Mo ako sa mga pinatnubayan Mo, pagkalooban Mo ako ng kapakanan kabilang sa mga pinagkalooban Mo ng kagalingan, isama Mo ako sa Iyong pangangalaga sa mga inalagaan Mo, pagpalain Mo ako sa kung ano ang Iyong ibinigay, at ipagtanggol mo ako sa kasamaan ng Iyong itinakda. Ikaw ay nag-utos at walang sinuman ang nag-utos laban sa Iyo, at ang iyong kaibigan ay hindi kailanman nahihihiya. Pinagpala at Dakila Ka, aming Panginoon.", "Sa panalangin ng witr — itinuro ito ng Propeta ﷺ kay Hasan ibn Ali (RA).", "Ang Sunnah qunoot ng witr. (Sa mga Hanafi, kilala rin ang 'Allahumma inna nasta'inuka'.)"),
        "dua_qunoot_hanafi" to DuaText("Qunoot (Allahumma Inna Nasta'inuka)", "O Allah, kami ay humihingi ng Iyong tulong at Iyong kapatawaran, naniniwala kami sa Iyo at umaasa sa Iyo, pinupuri Ka namin sa pinakamabuting paraan, nagpapasalamat kami sa Iyo at hindi nagmamasid, at iniiwan namin ang sinumang sumuway sa Iyo. O Allah, Ikaw lamang ang aming sinasamba, sa Iyo kami nagdarasal at nagpapatirapa, sa Iyo kami ay nagmamadali at nagsusumikap, umaasa kami sa Iyong awa at natatakot sa Iyong kaparusahan; tiyak na ang Iyong kaparusahan ay darating sa mga hindi naniniwala.", "Sa witr - ang pagsasagawa ng mga Hanafi.", "Iniulat mula kay Umar (RA) sa qunoot."),
        "dua_sleep_aslamtu" to DuaText("Mga Huling Salita Bago Matulog", "O Allah, isinusuko ko ang aking sarili sa Iyo, ipinagkakatiwala ko ang aking kapakanan sa Iyo at itinatalaga ko ang aking likod sa Iyong proteksyon, dahil sa pag-asa sa Iyo at sa takot sa Iyo. Walang kanlungan at walang pagtakas mula sa Iyo maliban sa Iyo. Ako ay naniniwala sa Iyong Aklat na Iyong ipinahayag at sa Iyong Propeta na Iyong isinugo.", "Pagkatapos ng wudu, nakahiga sa kanang bahagi — ang pinakahuling mga salita bago matulog.", "Kung siya ay mamatay sa gabing iyon, siya ay mamamatay sa fitrah (Islam)."),
        "dua_waking_night" to DuaText("Paggising sa Gabi", "Walang sinumang karapat-dapat sambahin maliban kay Allah, nag-iisa, walang katambal. Sa kanya ang kapangyarihan at sa Kanya ang papuri, at Siya ang may kapangyarihan sa lahat ng bagay. Ang lahat ng papuri ay para sa Allah, ang kaluwalhatian ay sa Allah, walang sinumang karapat-dapat sambahin maliban kay Allah, si Allah ang Pinakamadakila, at walang kapangyarihan o kapangyarihan maliban kay Allah. O Allah, patawarin mo ako.", "Sa paggising sa gabi.", "Ang kanyang dua ay sinasagot, at kung siya ay nag-wudu at nanalangin, ang kanyang panalangin ay tinatanggap."),
        "dua_hamm_ibn_masud" to DuaText("Dua para sa dalamhati (Ibn Mas'ud)", "O Allah, ako ay Iyong alipin, anak ng Iyong alipin, anak ng Iyong alipin. Ang aking noo ay nasa iyong kamay, ang iyong utos sa akin ay natupad, at ang iyong pasiya tungkol sa akin ay makatarungan. Hinihiling ko sa Iyo ang bawat pangalan na Iyo, kung saan Iyong pinangalanan ang Iyong Sarili, o ipinahayag sa Iyong Aklat, o itinuro sa sinuman sa Iyong nilikha, o itinatago sa Iyong sarili sa kaalaman ng hindi nakikita - na gawin Mo ang Quran na bukal ng aking puso, ang liwanag ng aking dibdib, ang pag-alis ng aking kalungkutan at ang pag-alis ng aking pag-aalala.", "Sa kalungkutan at paghihirap — pinalitan ng Allah ang kalungkutan ng kagalakan.", "Inalis ng Allah ang kanyang pag-aalala at kalungkutan at binibigyan siya ng kagalakan sa lugar nito."),
        "dua_difficulty_sahl" to DuaText("Kapag May Mahirap", "O Allah, walang madali maliban sa ginagawa Mong madali, at pinapadali Mo ang mahirap kung nais Mo.", "Kapag may nararamdamang mahirap.", "Kadalian sa mga pagsusulit at mahihirap na gawain."),
        "dua_musibah" to DuaText("Sa Isang Kapahamakan (Istirja)", "Tayo ay kay Allah at sa Kanya tayo babalik. O Allah, gantimpalaan mo ako sa aking paghihirap at palitan mo ako ng mas mabuti.", "Sa anumang pagkawala o kalamidad.", "Si Allah ay tiyak na nagbibigay ng isang bagay na mas mabuti — Umm Salamah (RA) ay ibinigay sa Propeta ﷺ."),
        "dua_debt" to DuaText("Para sa Kaluwagan sa Utang", "O Allah, sapat na sa akin ang Iyong ginawang matuwid laban sa kung ano ang Iyong ginawang labag sa batas, at sa pamamagitan ng Iyong kagandahang-loob ay gawin akong malaya sa lahat maliban sa Iyo.", "Para sa pagbabayad ng utang — itinuro ni Ali (RA).", "Kahit na ang utang ay parang bundok, si Allah ang babayaran nito."),
        "dua_anger" to DuaText("Kapag Galit", "Ako ay nagpapakupkop kay Allah mula sa Shaytan, ang isinumpa.", "Kapag galit.", "Ang Propeta ﷺ ay nagsabi: kung sasabihin niya ito, ang kanyang galit ay mawawala."),
        "dua_waswasa" to DuaText("Laban sa Waswasa sa Pananampalataya", "Naniniwala ako kay Allah at sa Kanyang mga Sugo.", "Kapag dumating ang mga bulong ni satanas tungkol sa pananampalataya.", "Kapag ang bulong ay dumating, sabihin ito at tumigil doon (at humingi din ng kanlungan sa Allah)."),
        "dua_travel_full" to DuaText("Kumpletuhin ang Pagsusumamo sa Paglalakbay", "O Allah, hinihiling namin sa Iyo sa paglalakbay na ito ang kabutihan at kabanalan, at ang mga gawaing nakalulugod sa Iyo. O Allah, gawing madali para sa amin ang paglalakbay na ito at paikliin ang distansya nito. O Allah, Ikaw ang Kasama sa paglalakbay at Tagapangalaga ng pamilya.", "Kapag nagtatakda sa isang paglalakbay, pagkatapos ng 'Subhanalladhi sakhkhara'.", "Ang kumpletong Sunnah travel dua."),
        "dua_return_travel" to DuaText("Pagbabalik mula sa Paglalakbay", "Tayo ay bumabalik, nagsisisi, sumasamba at nagpupuri sa ating Panginoon.", "Sa pagbabalik mula sa isang paglalakbay.", "Ang Propeta ﷺ ay nagsabi nito sa pagbabalik mula sa isang paglalakbay."),
        "dua_farewell_traveller" to DuaText("Nagbi-bid ng Paalam sa isang Manlalakbay", "Ipinagkatiwala ko kay Allah ang iyong relihiyon, ang iyong pagtitiwala at ang kahihinatnan ng iyong mga gawa.", "Kapag nagpaalam sa isang manlalakbay.", "Ang ipinagkatiwala kay Allah ay hindi kailanman mawawala."),
        "dua_entering_town" to DuaText("Paghinto sa isang Lugar", "Ako ay nagpapakupkop sa perpektong mga salita ni Allah mula sa kasamaan ng lahat ng Kanyang nilikha.", "Kapag huminto sa isang lugar o pagdating sa isang bagong bayan.", "Walang makakasama sa kanya hangga't hindi siya umaalis doon."),
        "dua_boarding_ship" to DuaText("Pagsakay sa Barko / Sasakyan", "Sa ngalan ng Allah ang paglalayag nito at ang pag-angkla nito. Tunay na ang aking Panginoon ay Mapagpatawad, Maawain.", "Kapag sumakay ng barko o sasakyan — ang mga salita ni Propeta Nuh (AS).", "Isang Quranikong taludtod — ang dua ng Nuh's (AS) arka."),
        "dua_istighfar_hayyul_qayyum" to DuaText("Istighfar kasama si Hayyul-Qayyum", "Ako ay humihingi ng kapatawaran mula sa Allah, maliban sa Kanya, ang Walang-hanggang Buhay, ang Tagapagtaguyod, at ako ay bumabaling sa Kanya sa pagsisisi.", "Para sa pagsisisi.", "Ang kanyang mga kasalanan ay pinatawad kahit na siya ay tumakas mula sa larangan ng digmaan."),
        "dua_rabbighfir_warham" to DuaText("Rabbighfir Warham", "Panginoon ko, patawarin mo at maawa ka, sapagkat Ikaw ang pinakamabuti sa mga nagpapakita ng awa.", "Isang Quranic na dua - para sa kapatawaran at awa.", "Ang huling taludtod ng Surah al-Mu'minun."),
        "dua_majlis_kaffarah" to DuaText("Kaffarat al-Majlis", "Luwalhati sa Iyo, O Allah, at papuri sa Iyo. Ako ay sumasaksi na walang diyos maliban sa Iyo. Humihingi ako ng Iyong kapatawaran at bumaling sa Iyo sa pagsisisi.", "Nang bumangon mula sa isang pagtitipon.", "Ito ay nagiging kabayaran sa anumang maling sinabi sa pagtitipon."),
        "dua_jami_forgiveness" to DuaText("Komprehensibong Pagpapatawad", "O Allah, patawarin Mo ako sa aking mga pagkakamali, sa aking kamangmangan, sa aking pagmamalabis sa aking mga gawain, at sa lahat ng Iyong higit na nalalaman kaysa sa akin.", "Isang komprehensibong dua ng Propeta ﷺ.", "Ang Propeta ﷺ ay gumawa ng dalawang ito."),
        "dua_parents_nuh" to DuaText("Dua ng Nuh (AS) para sa mga Magulang", "Panginoon ko, patawarin mo ako, ang aking mga magulang, ang sinumang pumasok sa aking bahay bilang isang mananampalataya, at ang lahat ng mananampalatayang lalaki at mananampalataya na mga babae.", "Para sa mga magulang at mga mananampalataya.", "Ang dua ni Propeta Nuh (AS)."),
        "dua_shukr_parents" to DuaText("Pasasalamat sa mga Magulang at Matuwid na Anak", "Panginoon ko, bigyan mo ako ng kakayahang magpasalamat sa Iyong biyaya na Iyong ipinagkaloob sa akin at sa aking mga magulang, at gumawa ng mga matuwid na gawa na nakalulugod sa Iyo, at gawing matuwid ang aking mga supling. Ako ay bumaling sa Iyo sa pagsisisi at ako ay kabilang sa mga nagpapasakop.", "Ang Quranikong dua ng pag-abot sa edad na apatnapu.", "Ang pasasalamat, mabubuting gawa at ang katuwiran ng mga anak ng isa — lahat sa isang dua."),
        "dua_intimacy" to DuaText("Bago ang Relasyon ng Mag-asawa", "Sa ngalan ni Allah. O Allah, ilayo mo sa amin si Shaytan at ilayo mo si Shaytan sa mga ipinagkaloob Mo sa amin (mga anak).", "Bago ang relasyon ng mag-asawa.", "Kung ang isang bata ay ipinag-uutos, hindi ito kailanman sasaktan ni Shaytan."),
        "dua_ibrahim_children_protection" to DuaText("Proteksyon ng Tahanan at mga Anak", "Panginoon, gawing ligtas ang lungsod na ito at ilayo mo ako at ang aking mga anak sa pagsamba sa mga diyus-diyosan.", "Ang dua ni Propeta Ibrahim (AS) — para sa kaligtasan ng lungsod at ng kanyang mga anak.", "Isang panalangin para sa pananatiling matatag sa tawhid."),
        "dua_drinking_milk" to DuaText("Kapag Umiinom ng Gatas", "O Allah, pagpalain mo kami at bigyan mo kami ng higit pa nito.", "Kapag umiinom ng gatas.", "Sapat na ang gatas bilang pagkain at inumin."),
        "dua_iftar_host" to DuaText("Kapag Nagbe-break Fast sa Iba", "Nawa'y masira ang pag-aayuno ng mga taong nag-aayuno sa iyo, nawa'y kainin ng mga matuwid ang iyong pagkain, at nawa'y ipanalangin ka ng mga anghel.", "Kapag nag-aayuno sa bahay ng isang tao.", "Ang ﷺ na dua ng Propeta para sa host."),
    )
}
